package br.com.erp;
import com.fasterxml.jackson.databind.JsonNode;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
class CashFlowTest extends ApiTestSupport {
 String auth,account;UUID branch,party;LocalDate today;
 @BeforeEach void fixture()throws Exception{auth=token(company);branch=db.queryForObject("SELECT id FROM branch WHERE tenant_id=?",UUID.class,tenant);today=LocalDate.parse(getApi("/api/v1/cash-flow/calendar",auth,200).get("date").asText());account=account(branch,"A");party=UUID.fromString(postApi("/api/v1/customers",auth,party("C"),201).get("id").asText());postApi("/api/v1/suppliers",auth,party("S"),201);}
 Map<String,Object> party(String code){return Map.of("code",code,"name","Parceiro","taxIdentifier","","contactName","","email","","phone","","address","","notes","");}
 String account(UUID branch,String code)throws Exception{return postApi("/api/v1/treasury/accounts",auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,"code",code,"name","Conta "+code,"kind","BANK"),201).get("id").asText();}
 UUID movement(String source,String destination,String amount)throws Exception{UUID id=UUID.randomUUID();var m=new HashMap<String,Object>();m.put("requestId",id);m.put("sourceId",source);m.put("destinationId",destination);m.put("amount",amount);m.put("note","Movimento de teste");postApi("/api/v1/treasury/movements",auth,m,200);return id;}
 JsonNode title(boolean incoming,String reference,String amount,LocalDate due)throws Exception{return postApi("/api/v1/"+(incoming?"receivables":"payables"),auth,Map.of("requestId",UUID.randomUUID(),"branchId",branch,incoming?"customerId":"supplierId",incoming?party:db.queryForObject("SELECT id FROM supplier WHERE tenant_id=?",UUID.class,tenant),"reference",reference,"document","","description","Título de teste","issuedOn",today.minusDays(30).toString(),"dueOn",due.toString(),"amount",amount),201);}
 UUID receipt(boolean incoming,JsonNode title,String amount,String bank)throws Exception{UUID id=UUID.randomUUID();var m=new HashMap<String,Object>();m.put(incoming?"receiptId":"paymentId",id);m.put("amount",amount);m.put(incoming?"receivedOn":"paidOn",today.toString());m.put("method","PIX");m.put("reference","");m.put("note","Registro de teste");m.put("treasuryAccountId",bank);postApi("/api/v1/"+(incoming?"receivables":"payables")+"/"+title.get("id").asText()+"/"+(incoming?"receipts":"payments"),auth,m,200);return id;}
 JsonNode report(LocalDate from,LocalDate to,String filter)throws Exception{return getApi("/api/v1/cash-flow?from="+from+"&to="+to+(filter==null?"":"&branchId="+filter),auth,200);}
 void amount(String expected,JsonNode node){assertEquals(0,new BigDecimal(expected).compareTo(new BigDecimal(node.asText())));assertTrue(node.isTextual());}
 void timestamp(UUID operation,String instant){db.update("UPDATE treasury_operation SET created_at=? WHERE tenant_id=? AND id=?",OffsetDateTime.parse(instant),tenant,operation);}
 @Test void emptyReportHasCompleteDailyCalendarAndZeroBalances()throws Exception{var r=report(today,today.plusDays(2),null);assertEquals(3,r.get("actual").size());assertEquals(3,r.get("pending").size());amount("0",r.get("summary").get("currentBalance"));amount("0",r.get("actual").get(2).get("closingBalance"));assertEquals("America/Sao_Paulo",r.get("zone").asText());}
 @Test void historicalOpeningClosingAndTimezoneBoundariesAreCorrect()throws Exception{var a=movement(null,account,"100");var b=movement(null,account,"20");var c=movement(account,null,"5");var d=movement(null,account,"7");timestamp(a,"2026-10-13T02:59:59Z");timestamp(b,"2026-10-13T03:00:00Z");timestamp(c,"2026-10-14T02:59:59Z");timestamp(d,"2026-10-14T03:00:00Z");var r=report(LocalDate.parse("2026-10-13"),LocalDate.parse("2026-10-13"),null);var s=r.get("summary");amount("122",s.get("currentBalance"));amount("100",s.get("openingBalance"));amount("115",s.get("closingBalance"));amount("20",s.get("inflows"));amount("5",s.get("outflows"));}
 @Test void transfersAreSeparateAndNetZeroAcrossBothBranches()throws Exception{movement(null,account,"100");UUID other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra"),201).get("id").asText());String destination=account(other,"B");movement(account,destination,"30");var all=report(today,today,null).get("summary");amount("100",all.get("inflows"));amount("0",all.get("outflows"));amount("30",all.get("transferIn"));amount("30",all.get("transferOut"));amount("100",all.get("closingBalance"));var first=report(today,today,branch.toString()).get("summary");amount("0",first.get("transferIn"));amount("30",first.get("transferOut"));amount("70",first.get("closingBalance"));}
 @Test void partiallySettledTitlesOnlyProjectOutstandingAndDoNotDuplicateLinkedEntries()throws Exception{movement(null,account,"100");var incoming=title(true,"IN","100",today.plusDays(1));var outgoing=title(false,"OUT","80",today.plusDays(1));receipt(true,incoming,"40",account);receipt(false,outgoing,"20",account);var r=report(today,today.plusDays(1),null);var s=r.get("summary");amount("140",s.get("inflows"));amount("20",s.get("outflows"));amount("120",s.get("currentBalance"));amount("60",s.get("pendingReceivables"));amount("60",s.get("pendingPayables"));amount("0",r.get("pending").get(1).get("net"));amount("0",s.get("unlinkedReceipts"));}
 @Test void cancelledSettledAndReversedTitlesHaveCorrectProjectionAndActuals()throws Exception{var paid=title(true,"PAID","50",today);UUID id=receipt(true,paid,"50",account);var cancelled=title(false,"CANCEL","80",today);postApi("/api/v1/payables/"+cancelled.get("id").asText()+"/cancel",auth,Map.of("version",0,"note","Cancelamento de teste"),200);var before=report(today,today,null).get("summary");amount("0",before.get("pendingReceivables"));amount("0",before.get("pendingPayables"));postApi("/api/v1/receivables/"+paid.get("id").asText()+"/receipts/"+id+"/reverse",auth,Map.of("requestId",UUID.randomUUID(),"note","Estorno de teste"),200);var after=report(today,today,null).get("summary");amount("50",after.get("inflows"));amount("50",after.get("outflows"));amount("0",after.get("currentBalance"));amount("50",after.get("pendingReceivables"));}
 @Test void overdueIsCurrentSnapshotAndDueTodayIsNotOverdue()throws Exception{title(true,"OLD","70",today.minusDays(1));title(true,"TODAY","20",today);title(false,"OLD","60",today.minusDays(1));var s=report(today,today,null).get("summary");amount("70",s.get("overdueReceivables"));amount("60",s.get("overduePayables"));amount("20",s.get("pendingReceivables"));amount("0",s.get("pendingPayables"));}
 @Test void unlinkedRecordsAreReportedWithoutChangingCashBalances()throws Exception{var r=title(true,"IN","100",today);var p=title(false,"OUT","80",today);receipt(true,r,"30",null);receipt(false,p,"20",null);var s=report(today,today,null).get("summary");amount("30",s.get("unlinkedReceipts"));amount("20",s.get("unlinkedPayments"));amount("0",s.get("currentBalance"));amount("0",s.get("inflows"));amount("0",s.get("outflows"));amount("70",s.get("pendingReceivables"));amount("60",s.get("pendingPayables"));}
 @Test void scopeAppliesToBalancesMovementsPendingOverdueAndBranchFilter()throws Exception{movement(null,account,"100");title(true,"VISIBLE","50",today);UUID visible=branch,other=UUID.fromString(postApi("/api/v1/branches",auth,Map.of("code","OTHER","name","Outra"),201).get("id").asText());String hidden=account(other,"B");movement(null,hidden,"200");branch=other;title(true,"HIDDEN","900",today.minusDays(1));branch=visible;UUID user=db.queryForObject("SELECT id FROM app_user WHERE tenant_id=?",UUID.class,tenant);db.update("UPDATE app_user SET all_branches=FALSE WHERE id=?",user);db.update("INSERT INTO user_branch_access(tenant_id,user_id,branch_id) VALUES(?,?,?)",tenant,user,visible);var s=report(today,today,null).get("summary");amount("100",s.get("currentBalance"));amount("100",s.get("inflows"));amount("50",s.get("pendingReceivables"));amount("0",s.get("overdueReceivables"));getApi("/api/v1/cash-flow?from="+today+"&to="+today+"&branchId="+other,auth,404);}
 @Test void tenantAndAllRequiredPermissionsAreEnforced()throws Exception{movement(null,account,"100");String other="other-"+UUID.randomUUID();provisioning.create("Outra",other,"Admin","admin@example.com",password);amount("0",getApi("/api/v1/cash-flow?from="+today+"&to="+today,token(other),200).get("summary").get("currentBalance"));for(String permission:List.of("cashflow:read","treasury:read","payable:read","receivable:read")){db.update("DELETE FROM user_permission WHERE tenant_id=? AND permission=?",tenant,permission);getApi("/api/v1/cash-flow?from="+today+"&to="+today,auth,403);db.update("INSERT INTO user_permission(tenant_id,user_id,permission) SELECT tenant_id,id,? FROM app_user WHERE tenant_id=?",permission,tenant);}}
 @Test void invalidIntervalsAndMissingDatesAreRejected()throws Exception{getApi("/api/v1/cash-flow?from="+today+"&to="+today.minusDays(1),auth,400);getApi("/api/v1/cash-flow?from="+today+"&to="+today.plusDays(366),auth,400);getApi("/api/v1/cash-flow?from=invalid&to="+today,auth,400);getApi("/api/v1/cash-flow",auth,400);assertEquals(366,report(today,today.plusDays(365),null).get("actual").size());}
}
